exports.responseHandler = async (input, callback) => {
    try {
        // 1. Panggil API langsung menggunakan axios
        // Note: Di Kommunicate, axios sudah tersedia secara global. 
        // Untuk running lokal, Anda perlu const axios = require('axios');
        const resp = await axios.get("https://ceosuite-api.nikici.com/api/v1/offices/all", {
            headers: {
                'Authorization': 'Bearer token' // Ganti dengan Bearer token yang sebenarnya
            }
        });

        // 2. Ekstrak data array berdasarkan struktur JSON yang baru (di dalam data.result)
        let offices = [];
        if (resp.data && resp.data.data && Array.isArray(resp.data.data.result)) {
            offices = resp.data.data.result;
        } else {
            throw new Error("Struktur JSON tidak dikenali. 'data.result' tidak ditemukan.");
        }

        // 3. Filter data khusus untuk lokasi Jakarta
        const jakartaOffices = offices.filter(office => {
            const region = (office.region_name || "").toLowerCase();
            return region.includes('jakarta');
        });

        if (jakartaOffices.length === 0) {
            throw new Error("Tidak ada ruangan yang ditemukan untuk wilayah Jakarta.");
        }

        // 4. Mapping ke Payload Carousel Kommunicate
        const cardPayload = jakartaOffices.map(office => {
            const currency = office.price?.currency || "IDR";
            const priceVal = office.price?.price_per_hour;
            const priceStr = priceVal ? `${currency} ${priceVal.toLocaleString('id-ID')}` : "Contact us";

            // Membersihkan teks [Staging] atau [UAT] dari judul
            let cleanTitle = (office.name || "").replace(/\[Staging\]|\[UAT\]/gi, '').trim();

            const regionSplit = office.region_name ? office.region_name.split(',') : ['Jakarta'];
            const cleanSubtitle = regionSplit[regionSplit.length - 1]?.trim() || "Jakarta";

            // Ambil gambar pertama atau gunakan gambar kosong jika tidak ada
            const imageUrl = office.office_catalogue?.[0]?.url || "https://via.placeholder.com/720x280.png?text=No+Image";

            return {
                title: cleanTitle,
                subtitle: `${office.office_category_name} • ${cleanSubtitle}`,
                header: {
                    overlayText: `${priceStr} / hr`,
                    imgSrc: imageUrl
                },
                description: `Capacity: ${office.office_details?.capacity_person || 0} Pax\n${office.description || 'Premium workspace.'}`,
                titleExt: "Available",
                buttons: [
                    {
                        name: "Check Availability",
                        action: {
                            type: "link",
                            payload: {
                                url: `https://web-app-uat.ceosuite.com/product/${office.id}`,
                                openMode: "newTab"
                            }
                        }
                    }
                ]
            };
        });

        // 5. Format akhir response untuk Kommunicate
        const responseData = [
            {
                "message": "Here are our premium workspaces in Jakarta. Which one suits your needs?",
                "platform": "kommunicate",
                "metadata": {
                    "contentType": "300",
                    "templateId": "10",
                    "payload": cardPayload.slice(0, 10) // Limit 10 card
                }
            }
        ];

        callback(responseData);

    } catch (error) {
        // 6. Trace error untuk memudahkan proses debugging di log Kommunicate
        let errorMessage = error.message;

        // Tangkap isi response error jika API menolak akses (misal Token expired / HTTP 401)
        if (error.response && error.response.data) {
            errorMessage = JSON.stringify(error.response.data);
        }

        // Callback ke Kommunicate untuk memunculkan/men-trace error
        callback({ error: errorMessage });
    }
};
